#include <iostream>

int main() {
    constexpr int NUMBER_OF_ELEMENTS = 5;
    double numbers[NUMBER_OF_ELEMENTS];
    double sum = 0.0;

    for (int i = 0; i < NUMBER_OF_ELEMENTS; ++i) {
        std::cin >> numbers[i];
        sum += numbers[i];
    }

    double average = sum / NUMBER_OF_ELEMENTS;

    int count = 0;
    for (int i = 0; i < NUMBER_OF_ELEMENTS; ++i) {
        if (numbers[i] > average) {
            ++count;
        }
    }

    std::cout << "Average is " << average << "\n";
    std::cout << "Number of elements above the average " << count << "\n";

    return 0;
}

#include <iostream>

int main() {
    constexpr int SIZE = 4;
    double myList[SIZE]; // Uninitialized: contains indeterminate garbage values

    // Explicitly assign values to each slot
    myList[0] = 5.6;
    myList[1] = 4.5;
    myList[2] = 3.3;
    myList[3] = 13.2;

    for (int i = 0; i < SIZE; ++i) {
        std::cout << "myList[" << i << "] = " << myList[i] << "\n";
    }

    return 0;
}

#include <iostream>
#include <algorithm>

int main() {
    constexpr int SIZE = 4;
    double myList[SIZE];

    myList[0] = 5.6;
    myList[1] = 4.5;
    myList[2] = 3.3;
    myList[3] = 13.2;

    // Using elements in arithmetic expressions
    myList[2] = myList[0] + myList[1]; // 5.6 + 4.5 = 10.1
    myList[0]++;                       // 5.6 -> 6.6

    std::cout << "myList[0]: " << myList[0] << "\n";
    std::cout << "myList[2]: " << myList[2] << "\n";

    // Using std::max with array elements
    double larger = std::max(myList[1], myList[2]);
    std::cout << "Max between index 1 and 2: " << larger << "\n";

    return 0;
}
